<template><view :class="['app-page','doc-page',{dark}]"><ui-header :title="doc.title||'内容'" back/><view v-if="doc.title" class="document"><view class="doc-icon"><ui-icon name="document" :size="48" tone="brand"/></view><text class="doc-title">{{doc.title}}</text><text v-if="doc.subtitle" class="doc-sub">{{doc.subtitle}}</text><text v-for="(p,i) in paragraphs" :key="i" class="paragraph">{{p}}</text><text class="updated">最后更新：{{displayDateTime(doc.updatedAt||'-')}}</text></view><ui-page-status v-else :loading="loading" title="内容暂时无法显示" :description="error" @retry="load"/></view></template>
<script>import{isDark}from'@/utils/app';import{api}from'@/services/api';export default{data(){return{dark:false,type:'about',doc:{},loading:true,error:''}},computed:{paragraphs(){return String(this.doc.content||'').split(/\r?\n/).filter(Boolean)}},onLoad(q){this.dark=isDark();this.type=q.type||'about';this.load()},methods:{async load(){this.loading=true;this.error='';try{this.doc=await api.getDocument(this.type)}catch(e){this.doc={};this.error=e.message||'加载失败'}finally{this.loading=false}}}}</script>
<style scoped>.doc-page{padding-bottom:50rpx}.document{margin:24rpx 28rpx;padding:36rpx 32rpx;border-radius:24rpx;background:var(--surface);box-shadow:var(--shadow-card)}.doc-icon{width:82rpx;height:82rpx;margin-bottom:24rpx;display:flex;align-items:center;justify-content:center;border-radius:26rpx;background:var(--brand-soft)}.doc-title{display:block;margin-bottom:10rpx;font-size:36rpx;font-weight:900}.doc-sub{display:block;margin-bottom:28rpx;color:var(--muted);font-size:24rpx}.paragraph{display:block;margin-bottom:28rpx;font-size:27rpx;line-height:46rpx;color:var(--text-secondary)}.updated{color:var(--muted);font-size:21rpx}</style>
